CREATE DATABASE SCOPED CREDENTIAL gold_storage_credential
WITH IDENTITY = 'Managed Identity';

CREATE EXTERNAL DATA SOURCE gold_storage
WITH (
    LOCATION = 'https://stshowroomanalytics01.dfs.core.windows.net/gold/',
    CREDENTIAL = gold_storage_credential
);

SELECT TOP 10 *
FROM OPENROWSET(
    BULK 'fact_sales',
    DATA_SOURCE = 'gold_storage',
    FORMAT = 'DELTA'
) AS result;
